INSERT INTO "gorev" VALUES('4c72751dddcc47b48487fc50b0d1e1f4','915d303e41ee4cb59fa908401d277926',NULL,27,'gemini adaptoru uctan uca','ege/gemini_uctan_uca.md dosyasina tek satir yaz: gemini uctan uca calisti. Sonra `python --version` kosturup GERCEK ciktisini KANIT terminal satiri olarak bildir.','gemini hic gercek tur kosmadi; codex''te ayni durum uc hata cikardi','ege/gemini_uctan_uca.md yazilsin ve python surumu kanitlansin','ege/gemini_uctan_uca.md var ve `python --version` gercek ciktisi KANIT terminal satiri olarak bildirildi','["ege/gemini_uctan_uca.md"]','','iptal','normal',4,0,'2026-09-21T19:51:12+00:00','2026-09-21T19:58:09+00:00','[]','','','[]','[]',0,0,'');
