INSERT INTO "kanit" VALUES('f7bb37bb48e1480eb2aac434a756c4eb','7db1e540c42540eb95248f5bc0135bda','dosya','karsilastirma_rapor.md - 5 CLI tool comparison table and evaluation','File: C:\Users\pc\Desktop\AgentOfis\calisma\cinar\karsilastirma_rapor.md (32 lines, 3.7K)

