INSERT INTO "kanit" VALUES('4719080a7fc84f9a9f60bbdf0d745632','3229c9937f50488d8c1c4df53bd4041a','terminal','QUANTBOT Python dosya sayısı ve ana giriş noktası tespiti','Tarama sonuçları:
