INSERT INTO "olay" VALUES(113,'915d303e41ee4cb59fa908401d277926','cinar','12dc35e474284e4592a711bc271b4604','arac_sonuc','1	# -*- coding: utf-8 -*-
2	"""Motor arayuzu: cekirdegin motora bakan tek yuzu.
3	
