INSERT INTO "olay" VALUES(1229,'915d303e41ee4cb59fa908401d277926','yaprak',NULL,'ders','yaprak: Sadece görevde açıkça listelenen (sekiz) parametreyi ham --help metnine karşı doğrulamak yetmiyor; komutun geri kalan tüm kurulumu (ör. -p/stdin kullanımı) da aynı "birebir doğrula, yorumlama" disipliniyle kontrol edilmeli, aksi halde iş taşıdığı asıl fonksiyonu (prompt''u doğru iletmek) yerine getirmeyebilir.','2026-09-19T16:20:09+00:00');
INSERT INTO "olay" VALUES(1230,'915d303e41ee4cb59fa908401d277926','demir','2de428e26d05467ba334a7cec36366e6','ret','#7 geri gonderildi: gemini.py''de `komut = ["gemini", "-p", "-"]` + `process.stdin.write(metin)` kurgusu, gemini_help_raw.txt''deki "-p Appended to input on stdin (if any)" tanımına dayanmıyor; "-" değerinin stdin''den okuma anlamına geldiği ham metinde yok, dolayısıyla gerçek CLI''a giden prompt bozuk olabilir (literal "-" + metin). -p bayrağının kullanımını ham --help metnine dayanarak düzelt (ör. metni doğrudan -p değeri yap ya da stdin kullanımını ham metne göre kanıtla) ve bunu test_gemini.py''de nihai prompt içeriğini doğrulayan bir testle kanıtla.','2026-09-19T16:20:09+00:00');
