INSERT INTO "olay" VALUES(1282,'915d303e41ee4cb59fa908401d277926','demir','2de428e26d05467ba334a7cec36366e6','ret','#7 geri gonderildi: Sunulan kanitlarda "GEMINI_API_KEY sır sızması testi (log/exception''da geçmemeli)" diye bir test var denmiş ama calisma/gemini/test_gemini.py dosyasinda boyle bir test yok (grep ile dogrulandi: dosyada GEMINI_API_KEY sadece setup fixture''inda ve eksik-anahtar hata mesajinda gecen kontrolde var, sizinti/leak testi yok). Brifing acikca "hicbir log/print/exception mesajinda gecmesin diye kontrol et" diyor -- bu, testle dogrulanmasi gereken bir kosul, sadece kod incelemesiyle degil. Gercek bir test eklenmeli: API anahtari set edilip, tum yield edilen MotorOlayi''larinin govde/ek alanlarinda ve raise edilen MotorHatasi mesajlarinda anahtar degerinin gecmedigini dogrulayan bir test.','2026-09-19T16:22:12+00:00');
