INSERT INTO "olay" VALUES(2333,'915d303e41ee4cb59fa908401d277926','demir',NULL,'uyari','Plan reddedildi (1. deneme): Yazma alani proje kokunde YOK: calisma/cinar/test_panel_js.mjs
