INSERT INTO "olay" VALUES(3745,'915d303e41ee4cb59fa908401d277926','cinar','561f31dca7af490393b99e6b59a763af','cikti','Ret maddelerini inceledim. Ham `git status --short --untracked-files=all` çıktısı üç değişikliği gösteriyor:

