    sonraki         TEXT,
    etkin           INTEGER NOT NULL DEFAULT 1,
    son_calisma     TEXT,
    kaynak          TEXT NOT NULL DEFAULT 'insan',
    olusturuldu     TEXT NOT NULL
);
